package com.limitbeyond.training.internal;

import com.limitbeyond.identity.api.RoleGrantFacade;
import com.limitbeyond.shared.error.DomainException;
import com.limitbeyond.shared.rls.AuthContext;
import com.limitbeyond.shared.rls.AuthContextHolder;
import com.limitbeyond.training.domain.BodyMetric;
import com.limitbeyond.training.domain.DietPlan;
import com.limitbeyond.training.domain.Exercise;
import com.limitbeyond.training.domain.NutritionEntry;
import com.limitbeyond.training.domain.WorkoutLog;
import com.limitbeyond.training.persistence.BodyMetricRepository;
import com.limitbeyond.training.persistence.DietPlanRepository;
import com.limitbeyond.training.persistence.ExerciseRepository;
import com.limitbeyond.training.persistence.NutritionEntryRepository;
import com.limitbeyond.training.persistence.WorkoutLogRepository;
import com.limitbeyond.training.persistence.WorkoutSetRepository;
import com.limitbeyond.training.web.TrainingDtos;
import java.math.BigDecimal;
import java.time.Instant;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class TrainingService {
 private final ExerciseRepository exercises; private final WorkoutLogRepository workouts; private final WorkoutSetRepository workoutSets; private final BodyMetricRepository metrics; private final DietPlanRepository diets; private final NutritionEntryRepository nutritionEntries; private final RoleGrantFacade grants; private final HydrationRateLimiter hydrationRateLimiter;
 public TrainingService(ExerciseRepository exercises,WorkoutLogRepository workouts,WorkoutSetRepository workoutSets,BodyMetricRepository metrics,DietPlanRepository diets,NutritionEntryRepository nutritionEntries,RoleGrantFacade grants,HydrationRateLimiter hydrationRateLimiter){this.exercises=exercises;this.workouts=workouts;this.workoutSets=workoutSets;this.metrics=metrics;this.diets=diets;this.nutritionEntries=nutritionEntries;this.grants=grants;this.hydrationRateLimiter=hydrationRateLimiter;}

 @Transactional(readOnly=true)
 public List<TrainingDtos.ExerciseView> exercises(){AuthContext c=requireUser();if(c.gymId()==null&&!c.superAdmin())throw DomainException.forbidden("use gym training");return exercises.available(c.gymId()).stream().map(this::exerciseView).toList();}
 @Transactional
 public TrainingDtos.ExerciseView createExercise(TrainingDtos.ExerciseRequest r){AuthContext c=requireExerciseContext();requireExerciseEditor(c);return exerciseView(exercises.save(new Exercise(c.superAdmin()?null:c.gymId(),r.name(),r.discipline(),r.difficulty(),r.instructions(),r.primaryMuscleGroup(),r.secondaryMuscleGroup(),r.requiresWeight(),c.userId())));}
 @Transactional(readOnly=true) public TrainingDtos.ExerciseView exercise(UUID id){AuthContext c=requireExerciseContext();return exerciseView(availableExercise(id,c.gymId()));}
 @Transactional public TrainingDtos.ExerciseView updateExercise(UUID id,TrainingDtos.ExerciseRequest r){AuthContext c=requireExerciseContext();requireExerciseEditor(c);Exercise e=editableExercise(id,c);e.update(r.name(),r.discipline(),r.difficulty(),r.instructions(),r.primaryMuscleGroup(),r.secondaryMuscleGroup(),r.requiresWeight());return exerciseView(e);}
 @Transactional public void deleteExercise(UUID id){AuthContext c=requireExerciseContext();requireExerciseEditor(c);Exercise e=editableExercise(id,c);if(workoutSets.existsByExerciseId(id))throw DomainException.rule(com.limitbeyond.shared.error.ErrorCode.CONFLICT,"This exercise is already used in a workout and cannot be deleted.");exercises.delete(e);}

 @Transactional(readOnly=true)
 public List<TrainingDtos.WorkoutView> myWorkouts(UUID memberId){AuthContext c=requireUser();UUID target=memberId==null?c.userId():memberId;if(!target.equals(c.userId()))requireCoachFor(target);return workouts.findByUserIdOrderByPerformedAtDesc(target).stream().map(this::workoutView).toList();}
 @Transactional(readOnly=true) public List<TrainingDtos.WorkoutView> workoutsBetween(UUID memberId,java.time.LocalDate start,java.time.LocalDate end){java.time.Instant from=start.atStartOfDay(java.time.ZoneOffset.UTC).toInstant();java.time.Instant through=end.plusDays(1).atStartOfDay(java.time.ZoneOffset.UTC).toInstant();return myWorkouts(memberId).stream().filter(w->!w.performedAt().isBefore(from)&&w.performedAt().isBefore(through)).toList();}
 @Transactional(readOnly=true) public List<TrainingDtos.WorkoutView> workoutsByMuscle(UUID memberId,String muscle){String wanted=muscle.trim();return myWorkouts(memberId).stream().filter(w->w.targetMuscleGroups().stream().anyMatch(g->g.equalsIgnoreCase(wanted))||w.sets().stream().anyMatch(s->exercises.findById(s.exerciseId()).map(e->e.getPrimaryMuscleGroup().equalsIgnoreCase(wanted)||(e.getSecondaryMuscleGroup()!=null&&e.getSecondaryMuscleGroup().toLowerCase().contains(wanted.toLowerCase()))).orElse(false))).toList();}
 @Transactional(readOnly=true) public TrainingDtos.WorkoutView myWorkout(UUID id){return workoutView(accessibleWorkout(id,requireUser()));}
 @Transactional
 public TrainingDtos.WorkoutView createWorkout(TrainingDtos.WorkoutRequest r){AuthContext c=requireUser();UUID memberId=r.memberId()==null?c.userId():r.memberId();if(!memberId.equals(c.userId()))requireCoachFor(memberId);if(r.locationId()!=null&&!c.appliesAt(r.locationId()))throw DomainException.notFound("Location");
   var prior=workouts.findByUserIdAndIdempotencyKey(memberId,r.idempotencyKey());if(prior.isPresent())return workoutView(prior.get());validateExercises(r.sets().stream().map(TrainingDtos.SetInput::exerciseId).toList(),c.gymId());
   UUID trainerId=memberId.equals(c.userId())?null:c.userId();WorkoutLog w=new WorkoutLog(memberId,c.gymId(),r.locationId(),trainerId,r.title(),r.description(),array(r.targetMuscleGroups()),r.performedAt(),r.durationMinutes(),r.notes(),r.idempotencyKey());r.sets().forEach(s->w.addSet(draft(s)));return workoutView(workouts.save(w));}
 @Transactional
 public TrainingDtos.WorkoutView updateWorkout(UUID id,TrainingDtos.UpdateWorkoutRequest r){AuthContext c=requireUser();WorkoutLog w=accessibleWorkout(id,c);if(r.locationId()!=null&&!c.appliesAt(r.locationId()))throw DomainException.notFound("Location");validateExercises(r.sets().stream().map(TrainingDtos.SetInput::exerciseId).toList(),c.gymId());var drafts=r.sets().stream().map(this::draft).toList();var completed=w.completedSetKeys();w.clearSets();workouts.flush();w.replace(r.title(),r.description(),array(r.targetMuscleGroups()),r.performedAt(),r.durationMinutes(),r.notes(),r.locationId(),drafts);w.restoreCompletedSets(completed);return workoutView(w);}
 @Transactional public void deleteWorkout(UUID id){WorkoutLog w=accessibleWorkout(id,requireUser());workouts.delete(w);}
 @Transactional public TrainingDtos.WorkoutView completeWorkout(UUID id){WorkoutLog w=accessibleWorkout(id,requireUser());w.complete();return workoutView(w);}
 @Transactional public TrainingDtos.WorkoutView reopenWorkout(UUID id){WorkoutLog w=accessibleWorkout(id,requireUser());w.reopen();return workoutView(w);}
 @Transactional public TrainingDtos.WorkoutView markSet(UUID workoutId,UUID setId,boolean complete){WorkoutLog w=accessibleWorkout(workoutId,requireUser());if(w.getSets().stream().noneMatch(s->s.getId().equals(setId)))throw DomainException.notFound("Workout set");w.markSet(setId,complete);return workoutView(w);}
 @Transactional public TrainingDtos.WorkoutView completeExercise(UUID workoutId,UUID exerciseId){WorkoutLog w=accessibleWorkout(workoutId,requireUser());if(w.getSets().stream().noneMatch(s->s.getExerciseId().equals(exerciseId)))throw DomainException.notFound("Workout exercise");w.completeExercise(exerciseId);return workoutView(w);}
 @Transactional public TrainingDtos.WorkoutView copyWorkout(UUID id,TrainingDtos.CopyWorkoutRequest r){AuthContext c=requireUser();WorkoutLog source=accessibleWorkout(id,c);var prior=workouts.findByUserIdAndIdempotencyKey(source.getUserId(),r.idempotencyKey());if(prior.isPresent())return workoutView(prior.get());WorkoutLog copy=new WorkoutLog(source.getUserId(),c.gymId(),source.getLocationId(),source.getTrainerUserId(),source.getTitle(),source.getDescription(),source.getTargetMuscleGroups(),r.performedAt(),source.getDurationMinutes(),source.getNotes(),r.idempotencyKey());source.getSets().forEach(s->copy.addSet(new WorkoutLog.WorkoutSetDraft(s.getExerciseId(),s.getSetNumber(),s.getReps(),s.getWeightKg(),s.getSeconds(),s.getRpe(),s.getNotes())));return workoutView(workouts.save(copy));}
 @Transactional public TrainingDtos.WorkoutView addWorkoutExercise(UUID id,TrainingDtos.WorkoutExerciseRequest r){AuthContext c=requireUser();if(r.exerciseId()==null)throw DomainException.rule(com.limitbeyond.shared.error.ErrorCode.VALIDATION_FAILED,"Choose an exercise.");WorkoutLog w=accessibleWorkout(id,c);validateExercises(List.of(r.exerciseId()),c.gymId());int first=w.getSets().stream().filter(s->s.getExerciseId().equals(r.exerciseId())).mapToInt(s->s.getSetNumber()).max().orElse(0)+1;w.addSets(exerciseDrafts(r.exerciseId(),first,r.sets()));return workoutView(w);}
 @Transactional public TrainingDtos.WorkoutView replaceWorkoutExercise(UUID id,UUID exerciseId,TrainingDtos.WorkoutExerciseRequest r){AuthContext c=requireUser();WorkoutLog w=accessibleWorkout(id,c);validateExercises(List.of(exerciseId),c.gymId());w.removeExercise(exerciseId);w.addSets(exerciseDrafts(exerciseId,1,r.sets()));return workoutView(w);}
 @Transactional public TrainingDtos.WorkoutView removeWorkoutExercise(UUID id,UUID exerciseId){WorkoutLog w=accessibleWorkout(id,requireUser());if(w.getSets().stream().noneMatch(s->s.getExerciseId().equals(exerciseId)))throw DomainException.notFound("Workout exercise");w.removeExercise(exerciseId);return workoutView(w);}

 @Transactional(readOnly=true) public TrainingDtos.ProgressView myProgress(){return progressFor(requireUser().userId());}
 @Transactional(readOnly=true) public TrainingDtos.ProgressView userProgress(UUID userId){requireCoachFor(userId);return progressFor(userId);}
 @Transactional public TrainingDtos.MetricView addMyMetric(TrainingDtos.MetricRequest r){AuthContext c=requireUser();return saveMetric(c.userId(),c.gymId(),c.userId(),r);}
 @Transactional public TrainingDtos.MetricView addUserMetric(UUID userId,TrainingDtos.MetricRequest r){AuthContext c=requireCoachFor(userId);return saveMetric(userId,c.gymId(),c.userId(),r);}

 @Transactional(readOnly=true) public TrainingDtos.DietPlanView myDiet(){AuthContext c=requireUser();if(c.gymId()==null)return null;return diets.findByUserIdAndGymIdAndActiveTrue(c.userId(),c.gymId()).map(this::dietView).orElse(null);}
 @Transactional(readOnly=true) public TrainingDtos.DietPlanView userDiet(UUID userId){AuthContext c=requireCoachFor(userId);return diets.findByUserIdAndGymIdAndActiveTrue(userId,c.gymId()).map(this::dietView).orElse(null);}
 @Transactional public TrainingDtos.DietPlanView assignDiet(UUID userId,TrainingDtos.DietPlanRequest r){AuthContext c=requireCoachFor(userId);return saveDiet(userId,c,r);}
 @Transactional public TrainingDtos.DietPlanView assignMyDiet(TrainingDtos.DietPlanRequest r){AuthContext c=requireGym();requireNutritionEditor(c);return saveDiet(c.userId(),c,r);}
 @Transactional(readOnly=true) public List<TrainingDtos.DietPlanView> myDietHistory(){AuthContext c=requireGym();return diets.findByUserIdAndGymIdOrderByStartsOnDesc(c.userId(),c.gymId()).stream().map(this::dietView).toList();}
 @Transactional(readOnly=true) public List<TrainingDtos.DietPlanView> userDietHistory(UUID userId){AuthContext c=requireCoachFor(userId);return diets.findByUserIdAndGymIdOrderByStartsOnDesc(userId,c.gymId()).stream().map(this::dietView).toList();}
 @Transactional public void deactivateMyDiet(UUID id){AuthContext c=requireGym();requireNutritionEditor(c);deactivateDiet(id,c.userId(),c.gymId());}
 @Transactional public void deactivateUserDiet(UUID userId,UUID id){AuthContext c=requireCoachFor(userId);deactivateDiet(id,userId,c.gymId());}

 @Transactional(readOnly=true) public TrainingDtos.NutritionDayView myNutrition(LocalDate day){AuthContext c=requireGym();return nutritionDay(c.userId(),c.gymId(),day);}
 @Transactional(readOnly=true) public TrainingDtos.NutritionDayView userNutrition(UUID userId,LocalDate day){AuthContext c=requireCoachFor(userId);return nutritionDay(userId,c.gymId(),day);}
 @Transactional(readOnly=true) public List<TrainingDtos.NutritionHistoryDay> myNutritionHistory(int days){AuthContext c=requireGym();return nutritionHistory(c.userId(),days);}
 @Transactional(readOnly=true) public List<TrainingDtos.NutritionHistoryDay> userNutritionHistory(UUID userId,int days){requireCoachFor(userId);return nutritionHistory(userId,days);}
 @Transactional public TrainingDtos.NutritionEntryView addMyNutrition(TrainingDtos.NutritionEntryRequest r){AuthContext c=requireGym();validateHydrationChange(c.userId(),r);return nutritionEntryView(nutritionEntries.save(entry(c.userId(),c,r)));}
 @Transactional public TrainingDtos.NutritionEntryView addUserNutrition(UUID userId,TrainingDtos.NutritionEntryRequest r){AuthContext c=requireCoachFor(userId);validateHydrationChange(userId,r);return nutritionEntryView(nutritionEntries.save(entry(userId,c,r)));}
 @Transactional public List<TrainingDtos.NutritionEntryView> addMyNutritionBatch(List<TrainingDtos.NutritionEntryRequest> requests){AuthContext c=requireGym();return saveNutritionBatch(c.userId(),c,requests);}
 @Transactional public List<TrainingDtos.NutritionEntryView> addUserNutritionBatch(UUID userId,List<TrainingDtos.NutritionEntryRequest> requests){AuthContext c=requireCoachFor(userId);return saveNutritionBatch(userId,c,requests);}
 @Transactional public TrainingDtos.NutritionEntryView updateNutrition(UUID id,TrainingDtos.NutritionEntryRequest r){AuthContext c=requireUser();NutritionEntry e=accessibleNutritionEntry(id,c);e.update(r.loggedOn(),r.mealType(),r.foodName(),r.servingAmount(),r.servingUnit(),r.calories(),r.proteinG(),r.carbsG(),r.fatG(),r.fiberG(),r.waterMl(),r.source(),r.sourceRef(),r.notes());return nutritionEntryView(e);}
 @Transactional public void deleteNutrition(UUID id){nutritionEntries.delete(accessibleNutritionEntry(id,requireUser()));}

 private TrainingDtos.ProgressView progressFor(UUID userId){List<WorkoutLog> ws=workouts.findByUserIdOrderByPerformedAtDesc(userId).stream().filter(WorkoutLog::isCompleted).toList();return new TrainingDtos.ProgressView(metrics.findByUserIdOrderByRecordedOnDesc(userId).stream().map(this::metricView).toList(),records(ws),ws.size());}
 private List<TrainingDtos.PersonalRecord> records(List<WorkoutLog> ws){Map<UUID,TrainingDtos.PersonalRecord> out=new HashMap<>();Map<UUID,String> names=new HashMap<>();exercises.findAllById(ws.stream().flatMap(w->w.getSets().stream()).map(s->s.getExerciseId()).distinct().toList()).forEach(e->names.put(e.getId(),e.getName()));
  for(WorkoutLog w:ws)for(var s:w.getSets()){var old=out.get(s.getExerciseId());BigDecimal weight=s.getWeightKg();Integer reps=s.getReps();if(old==null||(weight!=null&&(old.maxWeightKg()==null||weight.compareTo(old.maxWeightKg())>0))||(reps!=null&&(old.maxReps()==null||reps>old.maxReps()))){out.put(s.getExerciseId(),new TrainingDtos.PersonalRecord(s.getExerciseId(),names.getOrDefault(s.getExerciseId(),"Exercise"),max(weight,old==null?null:old.maxWeightKg()),max(reps,old==null?null:old.maxReps()),w.getPerformedAt()));}}
  return new ArrayList<>(out.values());}
 private BigDecimal max(BigDecimal a,BigDecimal b){if(a==null)return b;if(b==null)return a;return a.max(b);} private Integer max(Integer a,Integer b){if(a==null)return b;if(b==null)return a;return Math.max(a,b);}
 private void validateExercises(List<UUID> ids,UUID gymId){if(exercises.available(gymId).stream().map(Exercise::getId).filter(ids::contains).distinct().count()!=ids.stream().distinct().count())throw DomainException.notFound("Exercise");}
 private AuthContext requireUser(){AuthContext c=AuthContextHolder.get();if(!c.isAuthenticated())throw DomainException.forbidden("use training");return c;} private AuthContext requireGym(){AuthContext c=requireUser();if(c.gymId()==null)throw DomainException.forbidden("use gym training");return c;}
 private AuthContext requireCoachFor(UUID userId){AuthContext c=requireGym();if(!c.isAdmin()&&!c.hasRole("TRAINER"))throw DomainException.forbidden("coach this member");if(!grants.belongsToGym(userId,c.gymId()))throw DomainException.notFound("Member");return c;}
 private WorkoutLog.WorkoutSetDraft draft(TrainingDtos.SetInput s){return new WorkoutLog.WorkoutSetDraft(s.exerciseId(),s.setNumber(),s.reps(),s.weightKg(),s.seconds(),s.rpe(),s.notes());}
 private List<WorkoutLog.WorkoutSetDraft> exerciseDrafts(UUID exerciseId,int first,List<TrainingDtos.ExerciseSetInput> sets){java.util.concurrent.atomic.AtomicInteger number=new java.util.concurrent.atomic.AtomicInteger(first);return sets.stream().map(s->new WorkoutLog.WorkoutSetDraft(exerciseId,number.getAndIncrement(),s.reps(),s.weightKg(),s.seconds(),s.rpe(),s.notes())).toList();}
 private TrainingDtos.ExerciseView exerciseView(Exercise e){return new TrainingDtos.ExerciseView(e.getId(),e.getGymId(),e.getName(),e.getDiscipline(),e.getDifficulty(),e.getInstructions(),e.getPrimaryMuscleGroup(),e.getSecondaryMuscleGroup(),e.isRequiresWeight());}
 private TrainingDtos.WorkoutView workoutView(WorkoutLog w){Map<UUID,String> names=new HashMap<>();exercises.findAllById(w.getSets().stream().map(s->s.getExerciseId()).distinct().toList()).forEach(e->names.put(e.getId(),e.getName()));return new TrainingDtos.WorkoutView(w.getId(),w.getUserId(),w.getTrainerUserId(),w.getTitle(),w.getDescription(),List.of(w.getTargetMuscleGroups()),w.getPerformedAt(),w.getDurationMinutes(),w.getNotes(),w.getLocationId(),w.isCompleted(),w.getCompletedAt(),w.getSets().stream().map(s->new TrainingDtos.SetView(s.getId(),s.getExerciseId(),names.getOrDefault(s.getExerciseId(),"Exercise"),s.getSetNumber(),s.getReps(),s.getWeightKg(),s.getSeconds(),s.getRpe(),s.getNotes(),s.getVolume(),s.isCompleted())).toList());}
 private WorkoutLog accessibleWorkout(UUID id,AuthContext c){WorkoutLog w=workouts.findById(id).orElseThrow(()->DomainException.notFound("Workout"));if(!w.getUserId().equals(c.userId()))requireCoachFor(w.getUserId());return w;}
 private String[] array(List<String> values){return values==null?new String[0]:values.stream().map(String::trim).filter(v->!v.isEmpty()).distinct().toArray(String[]::new);}
 private Exercise availableExercise(UUID id,UUID gymId){return exercises.findById(id).filter(e->e.getGymId()==null||e.getGymId().equals(gymId)).orElseThrow(()->DomainException.notFound("Exercise"));}
 private Exercise editableExercise(UUID id,AuthContext c){return exercises.findById(id).filter(e->c.superAdmin()?e.getGymId()==null:c.gymId().equals(e.getGymId())).orElseThrow(()->DomainException.notFound("Exercise"));}
 private void requireExerciseEditor(AuthContext c){if(!c.isAdmin()&&!c.hasRole("TRAINER"))throw DomainException.forbidden("manage exercises");}
 private void requireNutritionEditor(AuthContext c){if(!c.isAdmin()&&!c.hasRole("TRAINER"))throw DomainException.forbidden("manage nutrition goals");}
 private AuthContext requireExerciseContext(){AuthContext c=requireUser();if(c.gymId()==null&&!c.superAdmin())throw DomainException.forbidden("use gym training");return c;}
 private TrainingDtos.MetricView metricView(BodyMetric m){return new TrainingDtos.MetricView(m.getId(),m.getMetricType(),m.getRecordedOn(),m.getValue(),m.getUnit());}
 private TrainingDtos.MetricView saveMetric(UUID userId,UUID gymId,UUID recordedBy,TrainingDtos.MetricRequest r){BodyMetric metric=metrics.findByUserIdAndMetricTypeAndRecordedOn(userId,r.metricType(),r.recordedOn()).orElseGet(()->new BodyMetric(userId,gymId,r.metricType(),r.recordedOn(),r.value(),r.unit(),recordedBy));metric.updateMeasurement(r.value(),r.unit(),recordedBy);return metricView(metrics.save(metric));}
 private TrainingDtos.DietPlanView dietView(DietPlan d){return new TrainingDtos.DietPlanView(d.getId(),d.getObjective(),d.getContent(),d.getKcalTarget(),d.getProteinG(),d.getCarbsG(),d.getFatG(),d.getWaterMlTarget(),d.getFiberGTarget(),d.getStartsOn(),d.getEndsOn(),d.isActive());}
 private TrainingDtos.DietPlanView saveDiet(UUID userId,AuthContext c,TrainingDtos.DietPlanRequest r){diets.findByUserIdAndGymIdAndActiveTrue(userId,c.gymId()).ifPresent(old->{LocalDate lastEffectiveDay=r.startsOn().isAfter(old.getStartsOn())?r.startsOn().minusDays(1):old.getStartsOn();old.deactivateOn(lastEffectiveDay);diets.saveAndFlush(old);});return dietView(diets.save(new DietPlan(userId,c.gymId(),c.userId(),r.objective(),r.content(),r.kcalTarget(),r.proteinG(),r.carbsG(),r.fatG(),r.waterMlTarget(),r.fiberGTarget(),r.startsOn(),r.endsOn())));}
 private void deactivateDiet(UUID id,UUID userId,UUID gymId){DietPlan d=diets.findById(id).filter(p->p.getUserId().equals(userId)&&p.getGymId().equals(gymId)).orElseThrow(()->DomainException.notFound("Diet plan"));d.deactivate();}
 private NutritionEntry entry(UUID userId,AuthContext c,TrainingDtos.NutritionEntryRequest r){return new NutritionEntry(userId,c.gymId(),c.userId(),r.loggedOn(),r.mealType(),r.foodName(),r.servingAmount(),r.servingUnit(),r.calories(),r.proteinG(),r.carbsG(),r.fatG(),r.fiberG(),r.waterMl(),r.source(),r.sourceRef(),r.notes());}
 private List<TrainingDtos.NutritionEntryView> saveNutritionBatch(UUID userId,AuthContext c,List<TrainingDtos.NutritionEntryRequest> requests){requests.forEach(r->validateHydrationChange(userId,r));return nutritionEntries.saveAll(requests.stream().map(r->entry(userId,c,r)).toList()).stream().map(this::nutritionEntryView).toList();}
 private void validateHydrationChange(UUID userId,TrainingDtos.NutritionEntryRequest r){if(r.waterMl()==0)return;if(Math.abs(r.waterMl())!=500)throw DomainException.rule(com.limitbeyond.shared.error.ErrorCode.VALIDATION_FAILED,"Water can only be adjusted by 500 ml.");if(r.waterMl()<0&&totals(nutritionEntries.findByUserIdAndLoggedOnOrderByCreatedAtAsc(userId,r.loggedOn())).waterMl()<500)throw DomainException.rule(com.limitbeyond.shared.error.ErrorCode.VALIDATION_FAILED,"Water intake cannot go below zero.");hydrationRateLimiter.check(userId);}
 private TrainingDtos.NutritionEntryView nutritionEntryView(NutritionEntry e){return new TrainingDtos.NutritionEntryView(e.getId(),e.getLoggedOn(),e.getMealType(),e.getFoodName(),e.getServingAmount(),e.getServingUnit(),e.getCalories(),e.getProteinG(),e.getCarbsG(),e.getFatG(),e.getFiberG(),e.getWaterMl(),e.getSource(),e.getSourceRef(),e.getNotes(),e.getCreatedByUserId());}
 private TrainingDtos.NutritionDayView nutritionDay(UUID userId,UUID gymId,LocalDate day){var entries=nutritionEntries.findByUserIdAndLoggedOnOrderByCreatedAtAsc(userId,day);var plan=diets.findByUserIdAndGymIdOrderByStartsOnDesc(userId,gymId).stream().filter(p->!day.isBefore(p.getStartsOn())&&(p.getEndsOn()==null||!day.isAfter(p.getEndsOn()))).sorted(java.util.Comparator.comparing(DietPlan::isActive).reversed()).findFirst().map(this::dietView).orElse(null);return new TrainingDtos.NutritionDayView(day,plan,totals(entries),entries.stream().map(this::nutritionEntryView).toList());}
 private List<TrainingDtos.NutritionHistoryDay> nutritionHistory(UUID userId,int requestedDays){int days=Math.max(1,Math.min(90,requestedDays));LocalDate end=LocalDate.now();LocalDate start=end.minusDays(days-1);var grouped=nutritionEntries.findByUserIdAndLoggedOnBetweenOrderByLoggedOnAscCreatedAtAsc(userId,start,end).stream().collect(java.util.stream.Collectors.groupingBy(NutritionEntry::getLoggedOn));return start.datesUntil(end.plusDays(1)).map(day->new TrainingDtos.NutritionHistoryDay(day,totals(grouped.getOrDefault(day,List.of())))).toList();}
 private TrainingDtos.NutritionTotals totals(List<NutritionEntry> entries){BigDecimal calories=BigDecimal.ZERO,protein=BigDecimal.ZERO,carbs=BigDecimal.ZERO,fat=BigDecimal.ZERO,fiber=BigDecimal.ZERO;int water=0;for(var e:entries){calories=calories.add(e.getCalories());protein=protein.add(e.getProteinG());carbs=carbs.add(e.getCarbsG());fat=fat.add(e.getFatG());fiber=fiber.add(e.getFiberG());water+=e.getWaterMl();}return new TrainingDtos.NutritionTotals(calories,protein,carbs,fat,fiber,water);}
 private NutritionEntry accessibleNutritionEntry(UUID id,AuthContext c){NutritionEntry e=nutritionEntries.findById(id).orElseThrow(()->DomainException.notFound("Nutrition entry"));if(!e.getUserId().equals(c.userId()))requireCoachFor(e.getUserId());return e;}
}
